import numpy as np
import tensorflow as tf
import copy

class TensorList(list):
    @property
    def shape(self):
        if len(self) > 0 and hasattr(self[0], 'shape'):
            return (len(self),) + self[0].shape
        return (len(self),)

    @property
    def dtype(self):
        if len(self) > 0 and hasattr(self[0], 'dtype'):
            return self[0].dtype
        return np.dtype('float32')

    @property
    def ndim(self):
        return len(self.shape)

