    # Input 5: Higher dimensions (3D labels, 4D logits), float32, int32
    labels = np.random.randint(0, 5, size=(2, 3, 4)).astype(np.int32)
    logits = np.random.normal(0.0, 1.0, size=(2, 3, 4, 5)).astype(np.float32)
