    sizes = [1, 4, 4, 1]
    strides = [1, 6, 6, 1]
    rates = [1, 1, 1, 1]
    padding = 'VALID'
    name = "patch_extract_6"
    list_of_inputs.append({
        'images': images,
        'sizes': sizes,
        'strides': strides,
        'rates': rates,
        'padding': padding,
        'name': name
    })

    # Input 7: Small image matching size, float32, SAME padding
    images = np.random.rand(1, 4, 4, 1).astype(np.float32)
    sizes = [1, 4, 4, 1]
    strides = [1, 1, 1, 1]
    rates = [1, 1, 1, 1]
    padding = 'SAME'
    name = "patch_extract_7"
    list_of_inputs.append({
        'images': images,
        'sizes': sizes,
        'strides': strides,
        'rates': rates,
        'padding': padding,
        'name': name
    })

    # Input 8: Batch size > 1, multi-channel, int32 dtype
