    # Input 5: 3D array, float32, pos_weight 1D array (broadcastable)
    labels = np.array([[[0.1, 0.2], [0.3, 0.4]]], dtype=np.float32)
    logits = np.array([[[1.0, -1.0], [2.0, -2.0]]], dtype=np.float32)
