import tensorflow as tf
import numpy as np
import copy

def tf_raw_ops_SelfAdjointEigV2_inputs():
    list_of_inputs = []

    # Input 1
    input_dict = {
        "name": "eig_1",
        "input": np.array([[2.0, 1.0], [1.0, 2.0]], dtype=np.float32),
        "compute_v": True
    }
    list_of_inputs.append(copy.deepcopy(input_dict))

    # Input 2
    input_dict = {
        "name": "eig_2",
        "input": np.array([[1.0, -2.0], [-2.0, 5.0]], dtype=np.float64),
        "compute_v": False
    }
    list_of_inputs.append(copy.deepcopy(input_dict))

    # Input 3
    input_dict = {
        "name": "eig_3",
        "input": np.array([
            [[1.0, 0.5, 0.2], [0.5, 2.0, 0.1], [0.2, 0.1, 3.0]],
            [[4.0, 0.1, 0.3], [0.1, 5.0, 0.2], [0.3, 0.2, 6.0]]
        ], dtype=np.float32),
        "compute_v": True
    }
    list_of_inputs.append(copy.deepcopy(input_dict))

    # Input 4
    input_dict = {
        "name": "eig_4",
        "input": np.array([[1.0 + 0j, 2.0 - 1j], [2.0 + 1j, 3.0 + 0j]], dtype=np.complex64),
        "compute_v": True
    }
    list_of_inputs.append(copy.deepcopy(input_dict))

    # Input 5
    input_dict = {
        "name": "eig_5",
        "input": np.array([[5.0 + 0j, -1j], [1j, 2.0 + 0j]], dtype=np.complex128),
        "compute_v": False
    }
    list_of_inputs.append(copy.deepcopy(input_dict))

    # Input 6
    mat6 = np.zeros((2, 2, 2, 2), dtype=np.float32)
    for i in range(2):
        for j in range(2):
            mat6[i, j] = np.array([[float(i+j+1), 0.5], [0.5, float(i*j+2)]])
    input_dict = {
        "name": "eig_6",
        "input": mat6,
        "compute_v": True
    }
    list_of_inputs.append(copy.deepcopy(input_dict))

    # Input 7
    input_dict = {
        "name": "eig_7",
        "input": np.array([[3.0, -1.0], [-1.0, 2.0]], dtype=np.float32),
        "compute_v": True
    }
    list_of_inputs.append(copy.deepcopy(input_dict))

    # Input 8
    input_dict = {
        "name": "eig_8",
        "input": np.eye(4, dtype=np.float32),
        "compute_v": True
    }
    list_of_inputs.append(copy.deepcopy(input_dict))

    # Input 9
    input_dict = {
        "name": "eig_9",
        "input": np.array([
            [[1.0, 1j], [-1j, 2.0]],
            [[2.0, 3.0+2j], [3.0-2j, -1.0]],
            [[0.0, -1.0], [-1.0, 0.0]]
        ], dtype=np.complex128),
        "compute_v": False
    }
    list_of_inputs.append(copy.deepcopy(input_dict))

    # Input 10
    np.random.seed(42)
    temp = np.random.randn(5, 5)
    mat10 = (temp + temp.T).astype(np.float64)
    input_dict = {
        "name": "eig_10",
        "input": mat10,
        "compute_v": True
    }
    list_of_inputs.append(copy.deepcopy(input_dict))

    return list_of_inputs

generated_inputs["tf.raw_ops.SelfAdjointEigV2"] = generated_inputs.get("tf.raw_ops.SelfAdjointEigV2", []) + (tf_raw_ops_SelfAdjointEigV2_inputs())

