import numpy as np
import tensorflow as tf
import copy
from tensorflow.python.ops.numpy_ops import np_math_ops

def patch_closure(func, visited=None):
    if visited is None:
        visited = set()
    if id(func) in visited:
        return
    visited.add(id(func))
    if not hasattr(func, '__closure__') or func.__closure__ is None:
        return
    for cell in func.__closure__:
        try:
            val = cell.cell_contents
        except ValueError:
            continue
        if callable(val):
            if getattr(val, '__name__', '') == 'sort':
                original_op = val
                def wrapper_op(*args, **kwargs):
                    if 'order' in kwargs:
                        kwargs['order'] = None
                    args = list(args)
                    if len(args) > 3:
                        args[3] = None
                    return original_op(*args, **kwargs)
                cell.cell_contents = wrapper_op
                patch_closure(original_op, visited)
            else:
                patch_closure(val, visited)

# Patch both entry points
patch_closure(tf.experimental.numpy.sort)
patch_closure(np_math_ops.sort)

