class MockString(str):
    def __getattr__(self, name):
        if name == 'precision_mode':
            return 'FP32'
        elif name == 'max_workspace_size_bytes':
            return 1073741824
        elif name in ('minimum_segment_size', 'maximum_cached_engines'):
            return 3
        elif name in ('use_calibration', 'allow_build_at_runtime'):
            return True
        return None

