class CustomKeyValueTensorInitializer(tf.lookup.KeyValueTensorInitializer):
    def __init__(self, keys, values, **kwargs):
        super().__init__(keys, values, **kwargs)
        self._val_dtype = np.dtype(values.dtype)

    @property
    def shape(self):
        return ()

    @property
    def dtype(self):
        return self._val_dtype

