import numpy as np
import tensorflow as tf
import copy

class CallableIterable:
    def __iter__(self):
        return iter([])
    def __len__(self):
        return 0
    def __getitem__(self, index):
        raise IndexError("Index out of range")
    def __call__(self, inputs, num_spatial_dims, padding):
        return inputs

def tf_nn_with_space_to_batch_inputs():
    list_of_inputs = []

    def make_dict(inp, dil, pad, op, filt, spat, df):
        return {
            'input': inp,
            'dilation_rate': dil,
            'padding': pad,
            'op': op,
            'filter_shape': filt,
            'spatial_dims': spat,
            'data_format': df
        }

    # Input 1: 2D NHWC VALID
    list_of_inputs.append(make_dict(
        np.zeros((2, 4, 4, 3), dtype=np.float32),
        np.array([2, 2], dtype=np.int32),
        "VALID",
        CallableIterable(),
        np.array([1, 1], dtype=np.int32),
        [1, 2],
        "NHWC"
    ))

    # Input 2: 2D NHWC SAME
    list_of_inputs.append(make_dict(
        np.ones((1, 8, 8, 1), dtype=np.float32),
        np.array([2, 2], dtype=np.int32),
        "SAME",
        CallableIterable(),
        np.array([3, 3], dtype=np.int32),
        [1, 2],
        "NHWC"
    ))

    # Input 3: 1D NWC VALID
    list_of_inputs.append(make_dict(
        np.random.randn(2, 9, 3).astype(np.float32),
        np.array([3], dtype=np.int32),
        "VALID",
        CallableIterable(),
        np.array([1], dtype=np.int32),
        [1],
        "NWC"
    ))

    # Input 4: 1D NWC SAME
    list_of_inputs.append(make_dict(
        np.ones((1, 5, 2), dtype=np.float32),
        np.array([2], dtype=np.int32),
        "SAME",
        CallableIterable(),
        np.array([3], dtype=np.int32),
        [1],
        "NWC"
    ))

    # Input 5: 3D NDHWC VALID
    list_of_inputs.append(make_dict(
        np.zeros((1, 4, 4, 4, 1), dtype=np.float32),
        np.array([2, 2, 2], dtype=np.int32),
        "VALID",
        CallableIterable(),
        np.array([1, 1, 1], dtype=np.int32),
        [1, 2, 3],
        "NDHWC"
    ))

    # Input 6: 3D NDHWC SAME
    list_of_inputs.append(make_dict(
        np.ones((2, 3, 3, 3, 2), dtype=np.float32),
        np.array([1, 1, 1], dtype=np.int32),
        "SAME",
        CallableIterable(),
        np.array([3, 3, 3], dtype=np.int32),
        [1, 2, 3],
        "NDHWC"
    ))

    # Input 7: 2D NCHW VALID
    list_of_inputs.append(make_dict(
        np.zeros((2, 3, 4, 4), dtype=np.float32),
        np.array([2, 2], dtype=np.int32),
        "VALID",
        CallableIterable(),
        np.array([1, 1], dtype=np.int32),
        [2, 3],
        "NCHW"
    ))

    # Input 8: 2D NCHW SAME
    list_of_inputs.append(make_dict(
        np.ones((1, 2, 8, 8), dtype=np.float32),
        np.array([3, 3], dtype=np.int32),
        "SAME",
        CallableIterable(),
        np.array([3, 3], dtype=np.int32),
        [2, 3],
        "NCHW"
    ))

    # Input 9: 2D Non-contiguous Spatial Dims VALID
    list_of_inputs.append(make_dict(
        np.zeros((2, 4, 2, 4, 3), dtype=np.float32),
        np.array([2, 2], dtype=np.int32),
        "VALID",
        CallableIterable(),
        np.array([1, 1], dtype=np.int32),
        [1, 3],
        "NHWC"
    ))

    # Input 10: 1D NCW SAME
    list_of_inputs.append(make_dict(
        np.ones((2, 3, 6), dtype=np.float32),
        np.array([2], dtype=np.int32),
        "SAME",
        CallableIterable(),
        np.array([3], dtype=np.int32),
        [2],
        "NCW"
    ))

    return list_of_inputs

generated_inputs["tf.nn.with_space_to_batch"] = tf_nn_with_space_to_batch_inputs()

